create table public.drug_interactions(id bigint generated by default as identity primary key,business_id bigint references public.businesses(id) on delete cascade,drug_a_name text not null,drug_b_name text not null,severity text not null default 'moderate' check(severity in ('contraindicated','severe','moderate','minor')),description text not null,mechanism text,recommendation text,source text,category text,meta jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,drug_a_name,drug_b_name));
alter table public.drug_interactions enable row level security; revoke all on public.drug_interactions from anon,authenticated; grant select,insert,update,delete on public.drug_interactions to authenticated;
create policy drug_interactions_tenant on public.drug_interactions for all to authenticated using(business_id is null or business_id=(select private.current_business_id())) with check(business_id is null or business_id=(select private.current_business_id()));
create table public.doctor_activities(id bigint generated by default as identity primary key,doctor_id bigint not null references public.parties(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,medical_rep_id uuid references public.app_users(id) on delete set null,activity_date date not null,referral_count integer not null default 0,referral_amount numeric(10,2) not null default 0,prescription_count integer not null default 0,details jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(doctor_id,activity_date,business_id));
create table public.doctor_attention_scores(id bigint generated by default as identity primary key,doctor_id bigint not null references public.parties(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,calculated_date date not null,attention_score numeric(5,2) not null default 100,decline_percentage numeric(5,2) not null default 0,days_inactive integer not null default 0,last_referral_date date,baseline_referrals numeric(8,2) not null default 0,current_period_referrals integer not null default 0,previous_period_referrals integer not null default 0,status text not null default 'active',alert_reason text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.doctor_attention_alerts(id bigint generated by default as identity primary key,doctor_id bigint not null references public.parties(id) on delete cascade,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,medical_rep_id uuid references public.app_users(id) on delete set null,alert_type text not null,severity text not null,message text not null,details jsonb,is_sent boolean not null default false,sent_at timestamptz,is_read boolean not null default false,read_at timestamptz,action_taken boolean not null default false,action_details text,action_taken_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.doctor_attention_settings(id bigint generated by default as identity primary key,business_id bigint not null references public.businesses(id) on delete cascade,branch_id bigint references public.branches(id) on delete set null,referral_drop_threshold numeric(5,2) not null default 30,referral_drop_period_days integer not null default 30,inactivity_threshold_days integer not null default 14,critical_inactivity_days integer not null default 30,attention_score_warning numeric(5,2) not null default 60,attention_score_critical numeric(5,2) not null default 30,enable_push_notifications boolean not null default true,enable_email_notifications boolean not null default false,enable_sms_notifications boolean not null default false,notify_roles jsonb,notify_users jsonb,alert_frequency_hours integer not null default 24,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.doctor_activities enable row level security; alter table public.doctor_attention_scores enable row level security; alter table public.doctor_attention_alerts enable row level security; alter table public.doctor_attention_settings enable row level security;
revoke all on public.doctor_activities,public.doctor_attention_scores,public.doctor_attention_alerts,public.doctor_attention_settings from anon,authenticated; grant select,insert,update,delete on public.doctor_activities,public.doctor_attention_scores,public.doctor_attention_alerts,public.doctor_attention_settings to authenticated;
create policy doctor_activities_tenant on public.doctor_activities for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy doctor_attention_scores_tenant on public.doctor_attention_scores for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy doctor_attention_alerts_tenant on public.doctor_attention_alerts for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));
create policy doctor_attention_settings_tenant on public.doctor_attention_settings for all to authenticated using(business_id=(select private.current_business_id())) with check(business_id=(select private.current_business_id()));